import sys

class Array:
    def __init__(self, size=None, other=None):
        if other is not None:
            self.size = other.size
            self.data = other.data[:]
        else:
            self.size = size
            self.data = []
            if size > 0:
                line = sys.stdin.readline().strip()
                if line:
                    self.data = list(map(int, line.split()))

    def set_first(self, value):
        if self.size > 0:
            self.data[0] = value

    def __str__(self):
        return ' '.join(map(str, self.data))

def main():
    line = sys.stdin.readline().strip()
    if not line:
        return
    n = int(line)

    a1 = Array(size=n)

    a2 = Array(other=a1)

    modifyValue = int(sys.stdin.readline().strip())

    a1.set_first(modifyValue)

    print(f"Original: {a1}")
    print(f"Clone: {a2}")

if __name__ == "__main__":
    main()
